// QRWTY arm A: the open-work inventory of a Jeeves export, from its working tree. Lists the hooks
// (files and each process's report rows), every application-owned (`generated-extension`) file and
// whether it still has its generated bytes, and every route the report says answers 501 until it
// is written, with its loops. It never changes a file. Exit 1 only when the export is unreadable.
//
//   node tools/open-work.mjs <export dir> [--json]
import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";
import { join, relative } from "node:path";

const root = process.argv[2];
if (!root) {
  console.error("usage: node tools/open-work.mjs <export dir> [--json]");
  process.exit(2);
}
const manifest = JSON.parse(readFileSync(join(root, ".jeeves/manifest.json"), "utf8"));
const report = JSON.parse(readFileSync(join(root, ".jeeves/report.json"), "utf8"));
const sha = (path) => createHash("sha256").update(readFileSync(join(root, path))).digest("hex");
const walk = (dir) =>
  readdirSync(join(root, dir), { withFileTypes: true }).flatMap((e) => {
    const path = join(dir, e.name);
    if (e.isDirectory()) return ["node_modules", "dist", ".runtime"].includes(e.name) ? [] : walk(path);
    return [relative(".", path)];
  });

const hooksFiles = walk("src").filter((p) => /\.hooks\.[cm]?[jt]sx?$/.test(p)).sort();
const processes = report.processes.tiles.map((tile) => ({
  service: tile.service,
  shape: tile.shape,
  exposure: tile.exposure ?? null,
  hooks: tile.hooks,
  notImplemented: tile.routes
    .filter((r) => r.answers.startsWith("501"))
    .map((r) => ({ method: r.method, path: r.path, answers: r.answers })),
  loops: tile.loops,
}));
const applicationFiles = manifest.files
  .filter((f) => f.ownership === "generated-extension")
  .map((f) => ({ path: f.path, asGenerated: sha(f.path) === f.sha256 }));
const inventory = {
  hooks: { files: hooksFiles, processRows: processes.flatMap((p) => p.hooks) },
  applicationFiles,
  stubModules: report.modules
    .filter((m) => m.status === "stub")
    .map((m) => ({ module: m.module, name: m.name, host: m.host, kind: m.kind })),
  processes,
  requiredGaps: report.gaps.filter((g) => g.required).length,
  applicationComplete: report.applicationComplete,
};
if (process.argv.includes("--json")) {
  console.log(JSON.stringify(inventory, null, 2));
} else {
  const unchanged = applicationFiles.filter((f) => f.asGenerated).length;
  console.log(`hooks: ${hooksFiles.length} files, ${inventory.hooks.processRows.length} process rows`);
  console.log(`application files: ${applicationFiles.length} (${unchanged} still as generated)`);
  console.log(`stub modules: ${inventory.stubModules.length}; required gaps: ${inventory.requiredGaps}`);
  for (const p of processes)
    console.log(
      `  ${p.service}: ${p.notImplemented.filter((r) => !r.path.endsWith("/*")).length} routes answer 501` +
        (p.loops.length ? `, loops: ${p.loops.map((l) => l.module ?? JSON.stringify(l)).join(", ")}` : ""),
    );
  console.log(`application complete: ${report.applicationComplete}`);
}
